def main() -> None:
    if len(PAPERS) != 36:
        raise SystemExit(f"Expected 36 papers, found {len(PAPERS)}")
    ids = [row["candidate_id"] for row in PAPERS]
    urls = [row["pdf_url"] for row in PAPERS]
    if len(ids) != len(set(ids)) or len(urls) != len(set(urls)):
        raise SystemExit("Duplicate candidate ID or PDF URL")
    existing: dict[str, str] = {}
    for path in (CORPUS, FIRST):
        with path.open(newline="", encoding="utf-8-sig") as handle:
            existing.update({norm(row["title"]): row.get("document_id") or row.get("candidate_id") or "existing" for row in csv.DictReader(handle)})
    duplicates = [(row["candidate_id"], existing[norm(row["title"])]) for row in PAPERS if norm(row["title"]) in existing]
    if duplicates:
        raise SystemExit(f"Existing title duplicates: {duplicates}")
    BATCH.mkdir(parents=True, exist_ok=True)
    with OUTPUT.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=FIELDS)
        writer.writeheader()
        writer.writerows(PAPERS)
    print(f"Wrote {len(PAPERS)} candidates to {OUTPUT}")


if __name__ == "__main__":
    main()
